package com.personal.assistant.module.lifemanagement.service;
import com.personal.assistant.common.exception.*;import com.personal.assistant.module.lifemanagement.dto.LifeManagementRequests.*;import com.personal.assistant.module.reminder.dto.ReminderRequest;import com.personal.assistant.module.reminder.service.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import java.math.*;import java.sql.Timestamp;import java.time.*;import java.util.*;
@Service public class LifeManagementService{private final JdbcTemplate jdbc;private final ReminderService reminders;private final SecretCryptoService crypto;public LifeManagementService(JdbcTemplate jdbc,ReminderService reminders,SecretCryptoService crypto){this.jdbc=jdbc;this.reminders=reminders;this.crypto=crypto;}
 public List<Map<String,Object>>habits(Long uid){List<Map<String,Object>>rows=jdbc.queryForList("select h.*,coalesce((select count(*) from habit_checkin c where c.habit_id=h.id and c.user_id=h.user_id and c.checkin_date>=current_date-29),0) completed_30d from habit h where h.user_id=? order by h.active desc,h.created_at desc",uid);return rows.stream().map(row->{Map<String,Object>x=new LinkedHashMap<>(row);Long id=((Number)row.get("id")).longValue();List<LocalDate>dates=jdbc.query("select checkin_date from habit_checkin where user_id=? and habit_id=? order by checkin_date desc",(rs,n)->rs.getDate(1).toLocalDate(),uid,id);x.put("streak",streak(dates));x.put("completionRate30d",BigDecimal.valueOf(((Number)row.get("completed_30d")).longValue()*100.0/30).setScale(1,RoundingMode.HALF_UP));return x;}).toList();}
 @Transactional public Long saveHabit(Long uid,Habit r){if(!Set.of("DAILY","WEEKLY").contains(r.frequency()))throw validation("习惯频率不支持");Long reminderId=r.remindTime()==null?null:reminders.create(uid,new ReminderRequest("CUSTOM",null,null,"习惯："+r.name(),"记得完成习惯打卡",r.remindTime()));return jdbc.queryForObject("insert into habit(user_id,name,frequency,target_count,metric_type,target_value,unit,active,reminder_id,created_at) values(?,?,?,?,?,?,?,?,?,now()) returning id",Long.class,uid,r.name(),r.frequency(),r.targetCount()==null?1:r.targetCount(),r.metricType(),r.targetValue(),r.unit(),!Boolean.FALSE.equals(r.active()),reminderId);}
 @Transactional public Long checkin(Long uid,Long habitId,Checkin r){owned("habit",uid,habitId);return jdbc.queryForObject("insert into habit_checkin(user_id,habit_id,checkin_date,value,note,source,created_at) values(?,?,?,?,?,?,now()) on conflict(user_id,habit_id,checkin_date) do update set value=excluded.value,note=excluded.note,source=excluded.source returning id",Long.class,uid,habitId,r.checkinDate(),r.value(),r.note(),StringUtils.hasText(r.source())?r.source():"MANUAL");}
 public Map<String,Object>healthTrend(Long uid,String metricType){List<Map<String,Object>>points=jdbc.queryForList("select c.checkin_date,c.value,h.unit from habit_checkin c join habit h on h.id=c.habit_id and h.user_id=c.user_id where c.user_id=? and h.metric_type=? and c.checkin_date>=current_date-365 order by c.checkin_date",uid,metricType);return Map.of("metricType",metricType,"points",points);}
 public List<Map<String,Object>>contacts(Long uid){return jdbc.queryForList("select * from contact where user_id=? order by follow_up_at nulls last,name",uid);}@Transactional public Long saveContact(Long uid,Contact r){Long id=jdbc.queryForObject("insert into contact(user_id,name,relationship,company,birthday,anniversary,last_contact_at,preferences,follow_up_at,note,created_at,updated_at) values(?,?,?,?,?,?,?,?,?,?,now(),now()) returning id",Long.class,uid,r.name(),r.relationship(),r.company(),r.birthday(),r.anniversary(),r.lastContactAt(),r.preferences(),r.followUpAt(),r.note());if(r.followUpAt()!=null){Long reminder=reminders.create(uid,new ReminderRequest("CUSTOM",id,null,"联系 "+r.name(),"联系人跟进提醒",r.followUpAt()));jdbc.update("update contact set reminder_id=? where id=? and user_id=?",reminder,id,uid);}return id;}
 @Transactional public void markContacted(Long uid,Long id){owned("contact",uid,id);jdbc.update("update contact set last_contact_at=?,updated_at=? where id=? and user_id=?",Timestamp.valueOf(LocalDateTime.now()),Timestamp.valueOf(LocalDateTime.now()),id,uid);}
 public List<Map<String,Object>>assets(Long uid){return jdbc.queryForList("select id,user_id,asset_type,name,purchase_date,purchase_amount,warranty_until,expires_at,location,sensitive,reminder_id,note,created_at,updated_at from household_asset where user_id=? order by expires_at nulls last,name",uid);}@Transactional public Long saveAsset(Long uid,Asset r){String encrypted=Boolean.TRUE.equals(r.sensitive())&&StringUtils.hasText(r.sensitiveDetails())?crypto.encrypt(r.sensitiveDetails()):null;Long id=jdbc.queryForObject("insert into household_asset(user_id,asset_type,name,purchase_date,purchase_amount,warranty_until,expires_at,location,sensitive,encrypted_details,note,created_at,updated_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?) returning id",Long.class,uid,r.assetType().toUpperCase(),r.name(),r.purchaseDate(),r.purchaseAmount(),r.warrantyUntil(),r.expiresAt(),r.location(),Boolean.TRUE.equals(r.sensitive()),encrypted,r.note(),Timestamp.valueOf(LocalDateTime.now()),Timestamp.valueOf(LocalDateTime.now()));LocalDate date=r.expiresAt()!=null?r.expiresAt():r.warrantyUntil();if(date!=null){Long reminder=reminders.create(uid,new ReminderRequest("CUSTOM",id,null,r.name()+" 即将到期","请检查家庭资产、合同、保单或保修状态",date.minusDays(30).atTime(9,0)));jdbc.update("update household_asset set reminder_id=? where id=? and user_id=?",reminder,id,uid);}return id;}
 public String revealAsset(Long uid,Long id,String verification){Map<String,Object>row=jdbc.queryForMap("select sensitive,encrypted_details from household_asset where id=? and user_id=?",id,uid);if(!"CONFIRM".equals(verification))throw new BusinessException(ErrorCode.UNAUTHORIZED,"需要二次确认");if(!Boolean.TRUE.equals(row.get("sensitive"))||row.get("encrypted_details")==null)return "";return crypto.decrypt(String.valueOf(row.get("encrypted_details")));}
 private int streak(List<LocalDate>dates){Set<LocalDate>set=new HashSet<>(dates);LocalDate date=LocalDate.now();if(!set.contains(date))date=date.minusDays(1);int count=0;while(set.contains(date)){count++;date=date.minusDays(1);}return count;}private void owned(String table,Long uid,Long id){Integer count=jdbc.queryForObject("select count(*) from "+table+" where id=? and user_id=?",Integer.class,id,uid);if(count==null||count==0)throw new BusinessException(ErrorCode.NOT_FOUND,"记录不存在");}private BusinessException validation(String m){return new BusinessException(ErrorCode.VALIDATION_ERROR,m);}}
